SELECT MONTH(s.opened_date) AS opened_month, CASE WHEN YEAR(s.opened_date) < 2024 THEN 'before_2024' WHEN YEAR(s.opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, MAX(i.last_restock) AS last_last_restock FROM inventory i INNER JOIN products p ON i.product_id = p.id LEFT OUTER JOIN stores s ON i.store_id = s.id GROUP BY MONTH(s.opened_date), CASE WHEN YEAR(s.opened_date) < 2024 THEN 'before_2024' WHEN YEAR(s.opened_date) = 2024 THEN '2024' ELSE 'after_2024' END;
